import { Component, inject, OnInit } from '@angular/core';
import { Router, RouterOutlet, ActivationEnd } from '@angular/router';
import { AuthModalComponent } from './components/auth-modal/auth-modal.component';
import { AuthService } from './services/auth.service';
import { NavigationHistoryService } from './services/navigation-history.service';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, AuthModalComponent],
  templateUrl: './app.html',
  styleUrl: './app.scss'
})
export class App implements OnInit {
  private readonly authService = inject(AuthService);
  private readonly router = inject(Router);
  private readonly navHistory = inject(NavigationHistoryService);

  ngOnInit() {
    this.authService.checkSession().subscribe();
    this.router.events.subscribe(event => {
      if (event instanceof ActivationEnd && event.snapshot.data?.['backPath']) {
        this.navHistory.recordBackPath(event.snapshot.data['backPath']);
      }
    });
  }
}
